        if (strcmp(table_name, expected->table_name) != 0 ||
            strcmp(column_name, expected->column_name) != 0) {
            continue;
        }

        saw_row = 1;
        failures += expect_int64(mylite_column_int64(stmt, columns_ordinal_column),
                                 expected->ordinal_position, "columns ordinal");
